// @generated by:gauntlet run:g-o-d-s-e-y-e-control-contract
import { randomUUID } from "node:crypto";
import {
  type AuditExportPage,
  CONTROL_API_HEADER,
  CONTROL_API_VERSION,
  ProjectResponse,
  parseControlResponse,
} from "@godseye/contracts";
import { FoundationEngine, verifyAuditExport } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { fixtureAdapter } from "./foundations-helpers.js";
import { projectInput } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";

describe("first-party owner HTTP contract", () => {
  let fixture: OwnerAuthFixture;
  let app: ReturnType<typeof createApp>;
  let engine: FoundationEngine;
  let headers: Headers;
  let provider: ReturnType<typeof fixtureAdapter>;

  beforeEach(async () => {
    fixture = await ownerAuthFixture();
    provider = fixtureAdapter();
    engine = new FoundationEngine(fixture.store, { adapters: [provider.adapter] });
    app = createApp(
      fixture.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      fixture.identity,
      engine,
    );
    headers = (await fixture.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
  });
  afterEach(async () => {
    await fixture.close();
  });

  function request(path: string, method = "GET", body?: unknown) {
    const requestHeaders = new Headers(headers);
    if (method !== "GET") requestHeaders.set("idempotency-key", randomUUID());
    return app.request(new URL(`/api/v1${path}`, fixture.origin), {
      method,
      headers: requestHeaders,
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
  }

  async function project(slug = projectInput.slug) {
    const response = await request("/projects", "POST", { ...projectInput, slug });
    expect(response.status).toBe(201);
    return ProjectResponse.parse(await response.json());
  }

  it("T-AC-12 T-AC-01 T34 protects OpenAPI and publishes the current first-party paths and mutation key", async () => {
    const anonymous = await app.request(new URL("/api/v1/openapi.json", fixture.origin), {
      headers: fixture.headers(),
    });
    expect(anonymous.status).toBe(401);
    const response = await request("/openapi.json");
    expect(response.status).toBe(200);
    expect(response.headers.get(CONTROL_API_HEADER)).toBe(CONTROL_API_VERSION);
    const document = (await response.json()) as {
      openapi: string;
      info: { version: string };
      paths: Record<string, { post?: { parameters?: { name: string; required?: boolean }[] } }>;
    };
    expect(document.openapi).toBe("3.1.0");
    expect(document.info.version).toBe(CONTROL_API_VERSION);
    for (const path of [
      "/api/v1/projects",
      "/api/v1/foundation/plans",
      "/api/v1/audit/export",
      "/api/v1/owner/security",
    ])
      expect(document.paths).toHaveProperty(path);
    expect(Object.keys(document.paths).some((path) => path.startsWith("/api/auth/"))).toBe(false);
    expect(
      document.paths["/api/v1/projects"]?.post?.parameters?.some(
        (parameter) => parameter.name.toLowerCase() === "idempotency-key" && parameter.required,
      ),
    ).toBe(true);
  });

  it("T34 refuses caller-supplied authority in strict resource requests", async () => {
    const saved = await project();
    const environment = saved.environments[0];
    if (!environment) throw new Error("Missing contract fixture environment");
    const response = await request("/foundation/resources", "POST", {
      projectId: saved.id,
      environmentId: environment.id,
      kind: "configuration",
      name: "Strict resource fixture",
      actor: { id: fixture.identity.ownerId, kind: "owner" },
    });
    expect(response.status).toBe(422);
    expect(
      await engine.listRuns({ id: fixture.identity.ownerId, kind: "owner", projectIds: [] }),
    ).toHaveLength(0);
  });

  it("T34 hides a producer's unrecognized authority field behind a bounded server error", async () => {
    const saved = await project();
    const marker = "unexpected-owner-authority-fixture";
    fixture.core.listProjects = async () => [{ ...saved, ownerRole: marker }];
    const response = await request("/projects");
    const text = await response.text();
    expect(response.status).toBe(500);
    expect(response.headers.get(CONTROL_API_HEADER)).toBe(CONTROL_API_VERSION);
    expect(text.length).toBeLessThan(1024);
    expect(text).not.toContain(marker);
    expect(text).not.toContain("ownerRole");
    expect(JSON.parse(text)).toMatchObject({
      error: {
        code: expect.any(String),
        message: expect.any(String),
        requestId: expect.any(String),
      },
    });
  });

  it("T34 bounds the public failure when a producer emits oversized metadata", async () => {
    const saved = await project();
    const description = "oversized-metadata-fixture".repeat(1000);
    fixture.core.listProjects = async () => [{ ...saved, description }];
    const response = await request("/projects");
    const text = await response.text();
    expect(response.status).toBe(500);
    expect(text.length).toBeLessThan(1024);
    expect(text).not.toContain("oversized-metadata-fixture");
    expect(JSON.parse(text)).toMatchObject({
      error: {
        code: expect.any(String),
        message: expect.any(String),
        requestId: expect.any(String),
      },
    });
  });

  it("T34 rejects a resource whose environment belongs to another project", async () => {
    const first = await project();
    const second = await project("other-contract-project");
    const environment = second.environments[0];
    if (!environment) throw new Error("Missing other contract environment");
    const response = await request("/foundation/resources", "POST", {
      projectId: first.id,
      environmentId: environment.id,
      kind: "configuration",
      name: "Cross-project resource",
    });
    expect(response.status).toBe(403);
    expect((await response.json()).error).toMatchObject({ code: expect.any(String) });
    expect(provider.executions).toHaveLength(0);
  });

  it("T34 rejects a plan reference registered in a different environment", async () => {
    const saved = await project();
    const development = saved.environments.find(
      (environment) => environment.kind === "development",
    );
    const production = saved.environments.find((environment) => environment.kind === "production");
    if (!development || !production) throw new Error("Missing contract environments");
    const resource = await request("/foundation/resources", "POST", {
      projectId: saved.id,
      environmentId: production.id,
      kind: "configuration",
      name: "Production-only config",
    });
    expect(resource.status).toBe(201);
    const { id } = (await resource.json()) as { id: string };
    const response = await request("/foundation/plans", "POST", {
      projectId: saved.id,
      environmentId: development.id,
      targetId: development.id,
      expectedRevision: saved.revision,
      adapterId: provider.adapter.id,
      command: {
        kind: "deployment.release",
        intent: "deploy",
        artifactDigest: `sha256:${"a".repeat(64)}`,
        configurationRef: id,
      },
      maxCostMicros: 0,
      tools: [],
      destinations: [],
    });
    expect(response.status).toBe(403);
    expect(
      await engine.listRuns({ id: fixture.identity.ownerId, kind: "owner", projectIds: [] }),
    ).toHaveLength(0);
    expect(provider.executions).toHaveLength(0);
  });

  it("T34 returns an unavailable capability when no qualified execution adapter exists", async () => {
    const unavailable = new FoundationEngine(fixture.store);
    app = createApp(
      fixture.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      fixture.identity,
      unavailable,
    );
    const saved = await project();
    const environment = saved.environments[0];
    if (!environment) throw new Error("Missing contract fixture environment");
    const resource = await request("/foundation/resources", "POST", {
      projectId: saved.id,
      environmentId: environment.id,
      kind: "configuration",
      name: "No adapter config",
    });
    const { id } = (await resource.json()) as { id: string };
    const response = await request("/foundation/plans", "POST", {
      projectId: saved.id,
      environmentId: environment.id,
      targetId: environment.id,
      expectedRevision: saved.revision,
      adapterId: "unqualified-provider",
      command: {
        kind: "deployment.release",
        intent: "deploy",
        artifactDigest: `sha256:${"a".repeat(64)}`,
        configurationRef: id,
      },
      maxCostMicros: 0,
      tools: [],
      destinations: [],
    });
    expect(response.status).toBe(503);
    expect(
      await unavailable.listRuns({ id: fixture.identity.ownerId, kind: "owner", projectIds: [] }),
    ).toHaveLength(0);
    expect(provider.executions).toHaveLength(0);
  });

  it("T37 exports read-only pages that verify against a separately retained anchor and rejects invalid cursors", async () => {
    await project();
    await project("second-audit-contract");
    const anchor = await (await request("/audit/anchor")).json();
    const pages: AuditExportPage[] = [];
    let cursor = 0;
    while (cursor < anchor.sequence) {
      const response = await request(`/audit/export?cursor=${cursor}&limit=2`);
      expect(response.status).toBe(200);
      const page = parseControlResponse(
        "GET",
        "/api/v1/audit/export",
        await response.json(),
        response.headers.get(CONTROL_API_HEADER) ?? "",
      ) as AuditExportPage;
      expect(page.to).toBeGreaterThan(cursor);
      pages.push(page);
      cursor = page.to;
    }
    expect(pages.length).toBeGreaterThan(1);
    expect(verifyAuditExport(pages, anchor)).toBe(true);
    expect(verifyAuditExport(pages.slice(0, -1), anchor)).toBe(false);
    for (const query of ["cursor=-1", "cursor=1.5", "limit=0", "limit=1001", "cursor=abc"])
      expect((await request(`/audit/export?${query}`)).status, query).toBe(422);
  });
});
